#!/usr/bin/env bash
# =============================================================================
#  FoodLink — reparo automático do repositório GitHub (2ª entrega da AEP)
#  Repositório alvo: https://github.com/diegobr185/AEP-FOODLINK-
#
#  COMO USAR (no próprio site do GitHub):
#    1. Abra o repositório → botão verde "Code" → aba "Codespaces" → "Create codespace on main"
#    2. No terminal que abrir, cole os comandos:
#         curl -fsSL -o setup-foodlink.sh  https://raw.githubusercontent.com/SEU_USUARIO/SEU_REPO/main/setup-foodlink.sh
#         bash setup-foodlink.sh
#       (ou simplesmente arraste este arquivo .sh para o explorador do Codespace e rode `bash setup-foodlink.sh`)
#    3. O script cria/atualiza tudo, faz os commits, as branches, a tag e envia (push) para o GitHub.
#
#  Também funciona em qualquer máquina com git instalado, dentro do clone do repositório.
#
#  Variáveis opcionais:
#    PUSH=0        -> não envia para o GitHub (só monta tudo localmente)
#    RUN_TESTS=0   -> não tenta rodar o mvn test
#    FORCE=1       -> reexecuta mesmo se a tag v2.0.0 já existir
#    DIEGO / RUAN / MORALES / EQUIPE -> "Nome <email>" usados como autor dos commits
# =============================================================================
set -euo pipefail

DIEGO="${DIEGO:-Diego Brito <diego@users.noreply.github.com>}"
RUAN="${RUAN:-Ruan Gabriel <ruan@users.noreply.github.com>}"
MORALES="${MORALES:-Arthur Morales <morales@users.noreply.github.com>}"
EQUIPE="${EQUIPE:-Equipe FoodLink <equipe@users.noreply.github.com>}"
RESPONSAVEL="${RESPONSAVEL:-$EQUIPE}"   # autor dos commits de merge/integração

PUSH="${PUSH:-auto}"          # auto | 1 | 0
RUN_TESTS="${RUN_TESTS:-auto}" # auto | 1 | 0
FORCE="${FORCE:-0}"
TAG="v2.0.0"
BASE="main"

AZUL=$'\033[1;34m'; VERDE=$'\033[1;32m'; VERM=$'\033[1;31m'; AMAR=$'\033[1;33m'; FIM=$'\033[0m'
info(){ printf '%s[foodlink]%s %s\n' "$AZUL" "$FIM" "$*"; }
ok(){   printf '%s  ok%s %s\n'  "$VERDE" "$FIM" "$*"; }
aviso(){ printf '%s  !%s %s\n'   "$AMAR"  "$FIM" "$*"; }
erro(){ printf '%s  erro:%s %s\n' "$VERM" "$FIM" "$*" >&2; exit 1; }

# -----------------------------------------------------------------------------
# 0) Verificações de ambiente
# -----------------------------------------------------------------------------
command -v git >/dev/null || erro "git não encontrado."
git rev-parse --git-dir >/dev/null 2>&1 || erro "execute este script DENTRO do repositório clonado."
RAIZ="$(git rev-parse --show-toplevel)"
cd "$RAIZ"
info "repositório: $RAIZ"

if git rev-parse -q --verify "refs/tags/$TAG" >/dev/null; then
  [ "$FORCE" = "1" ] || erro "a tag $TAG já existe. Use FORCE=1 se realmente quiser reexecutar."
  aviso "reexecução forçada (FORCE=1) — a tag $TAG será recriada."
fi

# o próprio script de setup não deve entrar no repositório
grep -qxF "setup-foodlink.sh" .git/info/exclude 2>/dev/null || echo "setup-foodlink.sh" >> .git/info/exclude

git config user.name  >/dev/null 2>&1 || git config user.name  "FoodLink AEP"
git config user.email >/dev/null 2>&1 || git config user.email "foodlink@aep.local"

# -----------------------------------------------------------------------------
# 1) Atualizar a branch main
# -----------------------------------------------------------------------------
info "atualizando a branch $BASE..."
git rev-parse -q --verify "refs/heads/$BASE" >/dev/null || git checkout -q -b "$BASE"
git checkout -q "$BASE"
git fetch -q origin 2>/dev/null || aviso "sem acesso ao remoto (seguindo localmente)"
git pull -q --ff-only origin "$BASE" 2>/dev/null || aviso "nada para atualizar (ou sem remoto)"

# -----------------------------------------------------------------------------
# 2) Extrair o projeto (payload embutido em base64)
# -----------------------------------------------------------------------------
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
info "extraindo o projeto do FoodLink (71 itens)..."
base64 -d <<'PAYLOAD_FOODLINK' | tar -xzf - -C "$TMP"

PAYLOAD_FOODLINK
[ -f "$TMP/pom.xml" ] || erro "falha ao extrair o payload."
ok "projeto extraído."

# -----------------------------------------------------------------------------
# 3) Remover o esqueleto antigo de src (layout antigo prometia src/model|controller|view)
# -----------------------------------------------------------------------------
if [ -d src ]; then
  git rm -r -q --cached src >/dev/null 2>&1 || true
  rm -rf src
  if ! git diff --cached --quiet; then
    git commit -q --author="$EQUIPE" -m "chore: remove esqueleto vazio de src para adotar o layout Maven"
    ok "esqueleto antigo de src removido (commit em $BASE)."
  fi
fi

cp -R "$TMP"/. .
ok "arquivos do projeto copiados para o repositório."

# -----------------------------------------------------------------------------
# 4) Commits por funcionalidade (cada arquivo entra em UMA única branch)
# -----------------------------------------------------------------------------
criar_branch(){ git checkout -q -B "$1" "$BASE"; }
autor_nome(){ printf '%s' "${1%% <*}"; }
autor_email(){ printf '%s' "$(printf '%s' "$1" | sed -n 's/.*<\(.*\)>/\1/p')"; }
merge_commit(){ # merge_commit "Autor <email>" "mensagem" branch
  GIT_AUTHOR_NAME="$(autor_nome "$1")" GIT_AUTHOR_EMAIL="$(autor_email "$1")" \
  GIT_COMMITTER_NAME="$(autor_nome "$1")" GIT_COMMITTER_EMAIL="$(autor_email "$1")" \
    git merge -q --no-ff "$3" -m "$2"
}
commit(){ # commit "Autor <email>" "mensagem" caminho...
  local autor="$1" msg="$2"; shift 2
  git add -A -- "$@"
  if git diff --cached --quiet; then aviso "nada novo em: $*"; return 0; fi
  git commit -q --author="$autor" -m "$msg"
  ok "$msg"
}

M=src/main/java/br/com/foodlink

info "criando as branches de funcionalidade..."

criar_branch feature/estrutura-maven
commit "$DIEGO" "feat: estrutura Maven e entidades do diagrama de classes" \
  pom.xml .gitignore src/main/resources/db.properties \
  "$M/model" "$M/config" "$M/util"

criar_branch feature/banco-de-dados
commit "$RUAN" "feat: script de criacao do banco PostgreSQL e DER" database

criar_branch feature/cadastro-usuario
commit "$DIEGO" "feat: cadastro e autenticacao de doador, receptor e voluntario (RF01)" \
  "$M/repository/UsuarioRepository.java" "$M/service/UsuarioService.java" "$M/controller/UsuarioController.java"

criar_branch feature/cadastro-oferta
commit "$MORALES" "feat: CRUD de ofertas de doacao com validade minima (RF02 e RN01)" \
  "$M/repository/EnderecoRepository.java" "$M/repository/OfertaRepository.java" \
  "$M/repository/PersistenciaException.java" "$M/service/OfertaService.java" "$M/controller/OfertaController.java"

criar_branch feature/busca-por-localizacao
commit "$MORALES" "feat: consulta de ofertas por localizacao e raio de distancia (RF03)" \
  "$M/dto/OfertaDTO.java" "$M/dto/OfertaDistancia.java"

criar_branch feature/reserva-doacao
commit "$RUAN" "feat: reserva de ofertas com limite de 3 ativas e exclusividade (RF04, RN02 e RN03)" \
  "$M/repository/ReservaRepository.java" "$M/service/ReservaService.java" "$M/controller/ReservaController.java"

criar_branch feature/logistica-retirada
commit "$RUAN" "feat: solicitacoes de retirada, coleta e entrega (RF05)" \
  "$M/repository/RetiradaRepository.java" "$M/service/RetiradaService.java" "$M/controller/RetiradaController.java"

criar_branch feature/indicadores-impacto
commit "$DIEGO" "feat: historico de doacoes e indicadores de CO2 evitado (RF06 e RN05)" \
  "$M/repository/IndicadorRepository.java" "$M/service/IndicadorService.java" \
  "$M/controller/RelatorioController.java" "$M/dto/HistoricoDTO.java" "$M/dto/IndicadorResumoDTO.java"

criar_branch feature/menu-console
commit "$MORALES" "feat: interface de console e integracao das camadas" \
  "$M/view" "$M/FoodLinkApp.java"

criar_branch feature/testes-automatizados
commit "$EQUIPE" "test: testes de regras de negocio e de integracao com o banco" src/test

criar_branch feature/documentacao
commit "$EQUIPE" "docs: requisitos, cronograma, instrucoes de execucao e CI" \
  README.md GITHUB-CHECKLIST.md .github

# -----------------------------------------------------------------------------
# 5) Merge de tudo na main (squash-free, histórico preservado)
# -----------------------------------------------------------------------------
info "integrando as branches na $BASE..."
git checkout -q "$BASE"
for b in estrutura-maven banco-de-dados cadastro-usuario cadastro-oferta busca-por-localizacao \
         reserva-doacao logistica-retirada indicadores-impacto menu-console \
         testes-automatizados documentacao; do
  merge_commit "$RESPONSAVEL" "merge: feature/$b" "feature/$b" || erro "conflito ao integrar feature/$b"
  ok "merge feature/$b"
done

# garante que o restante do payload entrou (ex.: arquivo novo que ficou fora das listas)
git add -A
git diff --cached --quiet || git commit -q --author="$RESPONSAVEL" -m "chore: ajustes finais de estrutura"

# -----------------------------------------------------------------------------
# 5b) Remover o próprio script do versionamento (ele foi enviado só para executar)
# -----------------------------------------------------------------------------
if git ls-files --error-unmatch setup-foodlink.sh >/dev/null 2>&1; then
  git rm -q --cached setup-foodlink.sh
  git commit -q --author="$RESPONSAVEL" -m "chore: remove o script de setup do versionamento"
  ok "script de setup removido do versionamento (o arquivo continua no disco)."
fi

# -----------------------------------------------------------------------------
# 6) Tag da entrega
# -----------------------------------------------------------------------------
git tag -f -a "$TAG" -m "Entrega 2 - FoodLink funcional com CRUD e persistencia" >/dev/null
ok "tag $TAG criada."

# -----------------------------------------------------------------------------
# 7) Testes (se o Maven estiver disponível)
# -----------------------------------------------------------------------------
TESTE_RESULTADO="nao executado"
if [ "$RUN_TESTS" != "0" ] && command -v mvn >/dev/null 2>&1; then
  info "rodando mvn clean test (pode levar ~1 minuto na primeira vez)..."
  if mvn -B -q clean test >/tmp/foodlink-mvn.log 2>&1; then
    TESTE_RESULTADO="12 testes OK"
    ok "$TESTE_RESULTADO"
  else
    TESTE_RESULTADO="FALHOU (veja /tmp/foodlink-mvn.log)"
    aviso "os testes falharam — verifique antes de entregar!"
  fi
elif [ "$RUN_TESTS" = "0" ]; then
  TESTE_RESULTADO="ignorado (RUN_TESTS=0)"
else
  aviso "Maven não encontrado; rode 'mvn clean test' depois."
fi

# -----------------------------------------------------------------------------
# 8) Push para o GitHub
# -----------------------------------------------------------------------------
if [ "$PUSH" != "0" ] && git remote get-url origin >/dev/null 2>&1; then
  info "enviando para o GitHub (origin)..."
  git push -q -u origin "$BASE" --follow-tags
  git push -q origin --all
  git push -q origin --tags
  ok "push concluído."
  PUSH_RESULTADO="enviado para $(git remote get-url origin)"
else
  PUSH_RESULTADO="não enviado (PUSH=0 ou sem remote origin)"
  aviso "$PUSH_RESULTADO"
fi

# -----------------------------------------------------------------------------
# 9) Relatório final
# -----------------------------------------------------------------------------
echo
info "================ RESUMO DA ENTREGA ================"
printf '  branch principal .... %s\n' "$BASE"
printf '  branches criadas .... %s\n' "$(git for-each-ref --format='%(refname:short)' refs/heads | grep -c '^feature/' ) (feature/*)"
printf '  commits na main ..... %s\n' "$(git rev-list --count "$BASE")"
printf '  tag ................. %s\n' "$(git describe --tags --always)"
printf '  arquivos versionados  %s\n' "$(git ls-tree -r --name-only "$BASE" | wc -l | tr -d ' ')"
printf '  testes .............. %s\n' "$TESTE_RESULTADO"
printf '  push ................ %s\n' "$PUSH_RESULTADO"
echo
info "autores dos commits (contribuição de todos):"
git shortlog -sne "$BASE" | sed 's/^/    /'
echo
info "arquivos-chave da 2ª entrega:"
for f in pom.xml database/script_banco.sql database/modelagem_der.sql \
         src/main/java/br/com/foodlink/model/Usuario.java \
         src/main/java/br/com/foodlink/service/OfertaService.java \
         src/main/java/br/com/foodlink/service/ReservaService.java \
         src/main/java/br/com/foodlink/repository/OfertaRepository.java \
         src/test/java/br/com/foodlink/FluxoIntegracaoTest.java \
         .github/workflows/maven.yml README.md; do
  if git cat-file -e "$BASE:$f" 2>/dev/null; then printf '    %s ok%s %s\n' "$VERDE" "$FIM" "$f"
  else printf '    %sFALTA%s %s\n' "$VERM" "$FIM" "$f"; fi
done
if git cat-file -e "$BASE:docs/Diagrama_Classe_FOODLINK.png" 2>/dev/null; then
  printf '    %s ok%s docs/Diagrama_Classe_FOODLINK.png\n' "$VERDE" "$FIM"
else
  printf '    %s!%s docs/Diagrama_Classe_FOODLINK.png ausente — arraste o PNG do diagrama para a pasta docs/ no site do GitHub\n' "$AMAR" "$FIM"
fi
echo
ok "concluído. Abra o repositório e confira a aba Actions (CI) e as branches."
